B.akr=s(["\u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0639\u0645\u0631\u0643 18 \u0639\u0627\u0645\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644\u060c \u0648\u0623\u0646 \u062a\u0643\u0648\u0646 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0635\u062d\u064a\u062d\u0629\u060c \u0648\u0645\u0646\u0647\u0627 \u0628\u0644\u062f\u0643. \u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0643\u0644 \u0645\u0627 \u064a\u062a\u0645 \u0645\u0646 \u062d\u0633\u0627\u0628\u0643\u060c \u0641\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0633\u0631\u064a\u0629 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631.","\u064a\u062d\u0642 \u0644\u0646\u0627 \u0625\u064a\u0642\u0627\u0641 \u0623\u0648 \u062d\u0630\u0641 \u0623\u064a \u062d\u0633\u0627\u0628 \u064a\u062e\u0627\u0644\u0641 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0623\u0648 \u064a\u0633\u064a\u0621 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0623\u0648 \u0644\u0644\u0645\u0646\u0635\u0629."],t.s)
B.aic=new A.fJ("\u0627\u0644\u062d\u0633\u0627\u0628",B.akr)
B.an3=s(["\u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0635\u062d\u0629 \u0645\u0627 \u062a\u0646\u0634\u0631\u0647 \u0645\u0646 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0648\u0635\u0648\u0631 \u0648\u0623\u0633\u0639\u0627\u0631 \u0648\u0648\u0635\u0641 \u0648\u0631\u0633\u0627\u0626\u0644 \u0648\u0628\u0644\u0627\u063a\u0627\u062a\u060c \u0648\u0639\u0646 \u0627\u0645\u062a\u0644\u0627\u0643\u0643 \u062d\u0642 \u0646\u0634\u0631\u0647\u060c \u0648\u0639\u0646 \u0627\u0644\u062a\u0632\u0627\u0645\u0647 \u0628\u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627 \u0641\u064a \u0628\u0644\u062f\u0643.","\u064a\u064f\u0645\u0646\u0639 \u0646\u0634\u0631: \u0627\u0644\u0633\u0644\u0639 \u0623\u0648 \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629 \u0644\u0644\u0642\u0627\u0646\u0648\u0646 \u0641\u064a \u0645\u0635\u0631 \u0623\u0648 \u0641\u064a \u0628\u0644\u062f\u0643\u060c \u0648\u0627\u0644\u0623\u062f\u0648\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062d\u062a\u0627\u062c \u0648\u0635\u0641\u0629 \u0637\u0628\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0633\u064a\u0621 \u0623\u0648 \u0627\u0644\u0645\u0636\u0644\u0644 \u0623\u0648 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644\u064a\u060c \u0648\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0622\u062e\u0631\u064a\u0646 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0628\u062f\u0648\u0646 \u0625\u0630\u0646\u0647\u0645\u060c \u0648\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0632\u0639\u062c\u0629 \u0627\u0644\u0645\u0643\u0631\u0631\u0629.","\u062a\u0645\u0646\u062d\u0646\u0627 \u0625\u0630\u0646\u0627\u064b \u0628\u0639\u0631\u0636 \u0645\u0627 \u062a\u0646\u0634\u0631\u0647 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0635\u0629 \u0648\u0645\u0634\u0627\u0631\u0643\u0629 \u0631\u0648\u0627\u0628\u0637\u0647\u060c \u0648\u064a\u062d\u0642 \u0644\u0646\u0627 \u062d\u0630\u0641 \u0623\u064a \u0645\u062d\u062a\u0648\u0649 \u0645\u062e\u0627\u0644\u0641."],t.s)
